-- Core entities. See docs/requirements.md ("Core entities") for the reasoning.
-- IDs are UUIDv7 generated by the app, so no defaults are set on id columns.

CREATE TABLE users (
    id         uuid PRIMARY KEY,
    idp_id     text        NOT NULL UNIQUE,
    version    bigint      NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE folders (
    id         uuid PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name       text        NOT NULL,
    parent_id  uuid        REFERENCES folders (id) ON DELETE CASCADE,
    depth      smallint    NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    -- Backstop only: the app enforces the depth limit inside the write transaction.
    CONSTRAINT folders_depth_check CHECK (depth BETWEEN 1 AND 3)
);

-- Sibling names are unique per parent, case-insensitively, including at the root (FR-26).
CREATE UNIQUE INDEX folders_sibling_name_key
    ON folders (user_id, COALESCE(parent_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name));

-- Supports ON DELETE CASCADE from a parent folder and subtree queries.
CREATE INDEX folders_parent_id_idx ON folders (parent_id);

CREATE TABLE favicons (
    id           uuid PRIMARY KEY,
    user_id      uuid  NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    host         text  NOT NULL,
    content_type text  NOT NULL,
    data         bytea NOT NULL,
    CONSTRAINT favicons_user_host_key UNIQUE (user_id, host)
);

CREATE TABLE bookmarks (
    id             uuid PRIMARY KEY,
    user_id        uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    url            text        NOT NULL,
    normalized_url text        NOT NULL,
    title          text        NOT NULL DEFAULT '',
    note           text        NOT NULL DEFAULT '',
    -- Backstop only: deleting a folder trashes its bookmarks first (FR-16).
    folder_id      uuid        REFERENCES folders (id) ON DELETE SET NULL,
    favicon_id     uuid        REFERENCES favicons (id) ON DELETE SET NULL,
    fetch_status   text        NOT NULL,
    -- Maintained by the app in the same transaction that changes title, url or content.
    search_vector  tsvector    NOT NULL DEFAULT ''::tsvector,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    -- Trash is not a table: a bookmark is trashed when deleted_at is set.
    deleted_at     timestamptz,
    CONSTRAINT bookmarks_fetch_status_check CHECK (fetch_status IN ('ok', 'failed', 'pending')),
    -- Live and trashed bookmarks both count, so a trashed URL still blocks a duplicate (FR-23).
    CONSTRAINT bookmarks_user_normalized_url_key UNIQUE (user_id, normalized_url)
);

-- Keyset pagination for the list and trash views.
CREATE INDEX bookmarks_list_idx ON bookmarks (user_id, deleted_at, created_at DESC, id DESC);
-- Folder views.
CREATE INDEX bookmarks_folder_idx ON bookmarks (user_id, folder_id);
-- Ranked full-text search.
CREATE INDEX bookmarks_search_idx ON bookmarks USING gin (search_vector);
-- The sweep that re-enqueues fetches that never got a job.
CREATE INDEX bookmarks_pending_idx ON bookmarks (created_at) WHERE fetch_status = 'pending';

-- Kept apart from bookmarks so list queries never load page text.
-- No user_id here: this table is only reached through its bookmark.
CREATE TABLE bookmark_content (
    bookmark_id uuid PRIMARY KEY REFERENCES bookmarks (id) ON DELETE CASCADE,
    text        text NOT NULL
);
